<div class="space-y-6" x-data="{ confirmCancelId: null }"><div><h1 class="text-3xl font-bold">MY ORDERS</h1><p class="text-zinc-500">Track your campus food pre-orders and pickup status</p></div><div class="bg-white rounded-xl border border-zinc-200 overflow-hidden shadow-sm"><table class="min-w-full divide-y divide-zinc-200 text-sm"><thead class="bg-zinc-50 text-left font-semibold text-zinc-700"><tr><th class="px-6 py-3">Order ID</th><th class="px-6 py-3">Stall</th><th class="px-6 py-3">Items</th><th class="px-6 py-3">Pickup</th><th class="px-6 py-3">Total</th><th class="px-6 py-3">Status</th><th class="px-6 py-3">Payment</th><th class="px-6 py-3">Action</th></tr></thead><tbody class="divide-y divide-zinc-200">@forelse($orders as $order)<tr class="hover:bg-zinc-50"><td class="px-6 py-4 font-bold">#{{ str_pad($order->id, 3, '0', STR_PAD_LEFT) }}</td><td class="px-6 py-4">{{ $order->stall->name }}</td><td class="px-6 py-4">@foreach($order->orderItems as $oi)<div>{{ $oi->foodItem->name }} (x{{ $oi->quantity }})</div>@endforeach</td><td class="px-6 py-4">{{ $order->pickup_time }}</td><td class="px-6 py-4 font-semibold">RM {{ number_format($order->total_amount, 2) }}</td><td class="px-6 py-4"><span class="px-2.5 py-1 rounded-full text-xs font-semibold bg-amber-100 text-amber-800">{{ $order->status }}</span></td><td class="px-6 py-4">{{ $order->payment_status }}</td><td class="px-6 py-4 flex gap-2"><flux:button size="xs" wire:click="selectOrder({{ $order->id }})">Details</flux:button>@if($order->status === 'Pending')<flux:button size="xs" variant="danger" x-on:click="confirmCancelId = {{ $order->id }}">Cancel</flux:button>@endif</td></tr>@empty<tr><td colspan="8" class="px-6 py-8 text-center text-zinc-500">You have not placed any orders yet.</td></tr>@endforelse</tbody></table></div>@if($selectedOrder)<div class="bg-white rounded-xl border border-zinc-200 p-6 shadow-sm"><h2 class="text-lg font-bold mb-2">ORDER DETAILS: #{{ str_pad($selectedOrder->id, 3, '0', STR_PAD_LEFT) }}</h2><p class="text-sm text-zinc-600">Stall: <strong>{{ $selectedOrder->stall->name }}</strong> | Pickup Time: <strong>{{ $selectedOrder->pickup_time }}</strong> | Status: <strong>{{ $selectedOrder->status }}</strong></p><ul class="mt-3 list-disc list-inside text-sm text-zinc-700">@foreach($selectedOrder->orderItems as $item)<li>{{ $item->foodItem->name }} &times; {{ $item->quantity }} @ RM {{ number_format($item->unit_price, 2) }}</li>@endforeach</ul></div>@endif <div x-show="confirmCancelId !== null" style="display: none;" class="fixed inset-0 bg-black/50 flex items-center justify-center z-50"><div class="bg-white rounded-xl p-6 max-w-sm w-full shadow-lg"><h3 class="text-lg font-bold">Cancel Pre-Order?</h3><p class="text-sm text-zinc-600 mt-2">Are you sure you want to cancel this pending order?</p><div class="mt-6 flex justify-end gap-3"><flux:button size="sm" x-on:click="confirmCancelId = null">Keep Order</flux:button><flux:button size="sm" variant="danger" x-on:click="$wire.cancelOrder(confirmCancelId); confirmCancelId = null">Yes, Cancel</flux:button></div></div></div></div>